export async function getExpansionFinance() {
  const actor = await requireCapability("expansion.manage")
  return db.transaction(async (tx) => {
    await tx.execute(sql`set transaction isolation level repeatable read`)
    await lockedActor(tx, actor)
    const partners = await rows(tx, sql`select p.id,u.display_name,coalesce((select sum(l.amount_pence) from expansion_commission_ledger l where l.partner_id=p.id),0)::text as earned_pence,coalesce((select sum(b.amount_pence) from expansion_payouts b where b.p
    const payments = await rows(tx, sql`select e.id,e.contract_id,e.reference,e.milestone,e.net_pence::text,e.gross_pence::text,e.reverses_event_id,e.refund_treatment,e.calculated_adjustment_pence::text,e.created_at,p.invoice_id,i.client_name_snapshot as clien
